import java.util.Scanner;
public class JInput2 {
	public static void main(String[] args) {
		//الخطوة 1: قراءة العدد الصحيح الاول الذي يدخله المستخدم
		Scanner scan = new Scanner(System.in);
		System.out.println("ادخل عددا صحيحا:");
		int num = scan.nextInt();
		//الخطوة 2: اطبع العدد الصحيح الذي ادخله المستخدم، ثم استقبل الاعداد التالية طالما ادخل المستخدم عددا يقع في النطاق من 30 الى 90 شاملة؛ وإلا توقف
		while ( num >= 30 && num <= 90 ) {
			System.out.println("العدد المدخل هو " + num);
			System.out.println("ادخل عددا صحيحا:");
			num = scan.nextInt(); 
		}
		scan.close();
		System.out.println("نهاية الادخال.");
	}
}
